script.text:

function load$GridVoucherDetail$(g) {
	g.add_itemValueChanged(onChange$GridVoucherDetail$);
	g.add_onResponseComplete(on$GridVoucherDetail$ResponseComplete);
	g.add_commandEvent(on$GridVoucherDetail$ExecuteCommand);
	&FormulaExpression;
	&ESG.LoadScriptHoverField;
	g.$h = [['voucherCode', 'String', g._voucherCode], 'ma_kh', 'ngay_lct', 'ma_dvcs', 'stt_rec'];
	udf$Detail$(g);
}
/* <flatten type="Javascript"> */
function dispose$GridVoucherDetail$(g) {
	g.$a = null;
	try {g.remove_commandEvent(on$GridVoucherDetail$ExecuteCommand);} catch (ex) {}
	try {g.remove_onResponseComplete(on$GridVoucherDetail$ResponseComplete);} catch (ex) {}
	try {g.remove_itemValueChanged(onChange$GridVoucherDetail$);} catch (ex) {}
}
function onChange$GridVoucherDetail$InvoiceNumber(o) {o.grid.request(o, 'InvoiceNumber', 'InvoiceNumber', ['so_hd', 'stt_rec_tt'], o.grid.$h, true);}
function onChange$GridVoucherDetail$(sender, eventArgs) {
	var o = eventArgs.get_object(), g = o.grid, f = g.get_element().parentForm, name = o.field.Name, v = $func.trim(f.getItemValue('loai_ct'));
	switch (name) {
		case 'tien_nt':
			if (v != '2' || f.getItemValue('ma_nt') == f._baseCurrency) g.validExpression(o, [g.$a.tien], [g.$a.t_tien_nt, g.$a.t_tien], null);
				else g.validExpression(o, [g.$a.tien_tggs], [g.$a.t_tien_nt, g.$a.t_tien], null);
			if (v == 1) {
				set$GridVoucherDetail$Payment(o, g, f);
				g.live(o, 'tt_qd');
			}
			break;
		case 'tien':
			g.validExpression(o, null, [g.$a.t_tien], null);
			break;
		case 'ty_gia_ht2':
			if (v == '2') g.validExpression(o, [g.$a.tien_tggs], [g.$a.t_tien_nt, g.$a.t_tien], null);
			break;
		default:
			break;
	}
}
/* </flatten> */
function on$GridVoucherDetail$ExecuteCommand(sender, e) {
	var action = e.type.Action, g = sender, f = g.get_element().parentForm, v = $func.trim(f.getItemValue('loai_ct'));
	switch (action) {&PaymentRequestScriptCheckGridAction;
		&Clipboard.Event.Before;
		&Clipboard.Event.Before.Request;
		&Clipboard.Event.Before.Process;
		&Clipboard.Event.After;
		&Clipboard.Event.After.Process;
		case 'AfterInsertRow':
			onchange$Item$(f.getItem('loai_ct'));
			break;
		case 'AfterRemoveRow':
			on$GridVoucherDetail$RowChange(g, f);
			break;
		case 'AfterCloneRow':
			g.setItemFieldValue('stt_rec0', e.type.Value, '');
			on$GridVoucherDetail$RowChange(g, f);
			break;
		case 'Check':
			&ESG.ScriptCheck;
			//if (f.getItemValue('contract_payment_phase_yn')) {if (!g.validRowExpression('s1', '[s1] != ""')) break;};
			if (v == '1') if (!g.validRowExpression('so_hd', '([so_hd] != "")')) break;
			if (v == '3') if !g.validRowExpression('ma_kh_i', '([ma_kh_i] != "")') break;
			if !g.validRowExpression('ma_td4', '(![f4_yn]) || ([ma_td4] != "")') break;
			break;
		case 'ImportData':
			if (f._action == 'View') break;
			if (v != '3') {
				$message.show(f._language == 'v' ? 'Loại phiếu thu không hợp lệ.' : 'Invalid voucher type.', String.format('$find(\'{0}\').focus(\'loai_ct\');', f.get_id()));
				break;
			};
			&ImportDetailImportDataCommand;;
			break;
		case 'Download':
			&UserDefinedDownload;
			break;
		case 'Retrieve':
			if (f._action == 'View') break;
			/*C*/
			if (e.type.Value == '30' || e.type.Value == '40') {
				if (!f.validFields('ngay_ct, loai_ct')) break;
					switch (e.type.Value) {
					case '30':
						if (f.getItemValue('s5') == 1) g.showForm('zCRCRMFilter');
						break;
					case '40':
						if (f.getItemValue('s5') == 2) g.showForm('zCRDMGDFilter');
						break;
					default:
						break;
					}
				break; 
			} 
			if (v == '3') break;
			if (!f.validFields('ma_kh, ngay_ct, loai_ct')) break;
			switch (e.type.Value) {
				case '10':
					if (v == '1') g.showForm('CRInvoiceFilter');
					break;
				case '20':
					g.showForm('CRRequestFilter');
					break;
				default:
					break;
			}
			break;
		&PaymentRequestCopying;
		&GridExtraToolbarExecuteCommandScript;
		case 'Generate':
			if (v == '2' || v == '3' ||v == '9') 
			RowAllocatePaymentPhase(f, g, g._activeRow, false);
//			getData$Generate(f, g, r);
//			if (g._item) g.showForm('zCBGenerateForm');
			break;
		default:
			break;
	}
}
function on$GridVoucherDetail$ResponseComplete(sender, e) {
	var g = e.object, context = e.type.Context, result = e.type.Result, o = e.type.Object, f = g.get_element().parentForm;
	switch (context) {
		case 'InvoiceNumber':
			g.setItemGridBehavior(o, [
				['tk_co', result[0].Value, result[1].Value, false],
				['ngay_hd', result[2].Value, null, false],
				['ma_nt_i', result[3].Value, null, false],
				['ty_gia_hd', result[4].Value, null, false],
				['tien_hd_nt', result[5].Value, null, false],
				['da_tt_nt', result[6].Value, null, false],
				['cl_nt', result[7].Value, null, false],
				['ma_vv', result[8].Value, '', false],
				['ma_bp', result[9].Value, '', false],
				['so_lsx', result[10].Value, '', false],
				['ma_sp', result[11].Value, '', false],
				['ma_hd', result[12].Value, '', false],
				['ma_phi', result[13].Value, '', false],
				['ma_ku', result[14].Value, '', false]
			]);
			set$GridVoucherDetail$Payment(o, g, f);
			g.live(o, 'tk_co');
			break;
		case 'Download':
			g._key = result[0].Value;
			break;
		case 'CreditAccount':
			g.setItemGridBehavior(o, [['f4_yn', result[0].Value, null, null]]);
			if (result[0].Value == 0) g.setItemGridBehavior(o, [['ma_td4', '', '', null]]);
			break;
		case 'AllocatePaymentPhase':
			AllocatePaymentPhase(f, g, result);
			break;
		case 'AllocatePaymentPhase$':
			AllocatePaymentPhase(f, g, result);
			if (g._q$PaymentPhase.length > 0) {
				var r = g._q$PaymentPhase[0], o = g._getItem(r, g._getColumnOrder('ma_hd'));
				o.row = r;
				g._q$PaymentPhase.splice(0, 1);
				g.request(o, 'AllocatePaymentPhase', 'AllocatePaymentPhase$', ['ma_hd', 'tien_nt'], g.$h, null);
			} else {
				f.warningPaymentPhase = 0;
				f._findButton('Ok').click();
			}
			break;
		&ESG.ScriptGridResponse;
		default:
			break;
	}
}
function AllocatePaymentPhase(w, z, result) {
	var first = true, row = 0, f1 = 'tien_pb, ma_dot', f2 = 'tien_nt, s1', fields = '';
	var k = 5, l0 = z._getColumnOrder('ma_hd');
	var v = $func.trim(w.getItemValue('loai_ct'));
	for (var i = 0; i < result.length; i++) {
		if (result[i][k] > 0) {
			if (first) row = z._activeRow;
			else {
				z._appendRow(true);
				row = z._rowCount;
			}

			var o = z._getItem(row, l0);
			o.row = row;

			z.setItemGridBehavior(o, [
				['tien_nt', result[i][k], null, null],
				['s1', result[i][1], null, null]
			]);

			if (v != '2' || w.getItemValue('ma_nt') == w._baseCurrency) z.validExpression(o, [z.$a.tien], [z.$a.t_tien_nt, z.$a.t_tien], null);
				else z.validExpression(o, [z.$a.tien_tggs], [z.$a.t_tien_nt, z.$a.t_tien], null);
			if (first) first = false;
		}
	}

	if (!first) on$GridVoucherDetail$RowChange(z, w);
}
/* <flatten type="Javascript"> */
function on$GridVoucherDetail$RowChange(g, f) {g.executeAggregate([g.$a.t_tien_nt, g.$a.t_tien]);}
function set$GridVoucherDetail$Payment(o, g, f) {
	var c = g._getItemValue(o.row, g._getColumnOrder('ma_nt_i'));
	if (c == f.getItemValue('ma_nt')) g.executeExpression(o, [g.$a.tt_nt]);
		else {
			if (c == f._baseCurrency) g.executeExpression(o, [g.$a.tt]);
				else g.executeExpression(o, [g.$a.tt_qd]);
		}
}
function onFocus$GridVoucherDetail$InvoiceNumber(o) {
	var g = $find(o.id.split('_inputCell_')[0]);
	g._enter(o);
	var f = g.get_element().parentForm;
	if (f._action == 'New' || f._action == 'Edit') o._controlBehavior.add_loading(on$Filter$Before$Loading);
}
function on$Filter$Before$Loading(sender, e) {
	var g = sender._element.grid, f = g.get_element().parentForm;
	a = [
		{Name: 'ma_dvcs', Type: 'String', Value: f.getItemValue('ma_dvcs')},
		{Name: 'stt_rec', Type: 'String', Value: f.getItemValue('stt_rec')},
		{Name: 'ma_kh', Type: 'String', Value: f.getItemValue('ma_kh')},
		{Name: 'ngay_lct', Type: 'DateTime', Value: f.getItemValue('ngay_lct')}
	];
	sender.set_memvars(a);
}

function flowMulti$ValidExpression(o, g, f, t) {
	if (t == '1') {
		g.validExpression(o, [g.$a.tien], [g.$a.t_tien_nt, g.$a.t_tien], null);
		set$GridVoucherDetail$Payment(o, g, f);
	}
}
function getData$Generate(f, g, r) {
	g._item = g._getItemValue(r, g._getColumnOrder('ma_hd'));
	g._value = g._getItemValue(r, g._getColumnOrder('tien_nt'));
	g._idNumber = f._action == 'New' ? '' : g._getItemValue(r, g._getColumnOrder('stt_rec'));
}
function on$GridVoucherDetail$ResponseCustomer(o, result) {
	var g = o.grid, f = g.get_element().parentForm, v = $func.trim(f.getItemValue('loai_ct'));

	var arrIndex_ma_kh = result.map(function(e) { return e.Name; }).indexOf('ma_kh');
	var arrIndex_ten_kh = result.map(function(e) { return e.Name; }).indexOf('ten_kh');

	if (v == '1') return;
	if (v != '3') f.setItemControlBehavior('ma_kh', result[arrIndex_ma_kh].Value, result[arrIndex_ten_kh].Value, null);
	if (v == '3') g.setItemGridBehavior(o, [['ma_kh_i', result[arrIndex_ma_kh].Value, result[arrIndex_ten_kh].Value, null]]);
}
function onChange$GridVoucherDetail$CreditAccount(o) {o.grid.request(o, 'CreditAccount', 'CreditAccount', ['tk_co'], o.grid.$h, true);}
function RowAllocatePaymentPhase(f, g, r, q) {
	var v = $func.trim(f.getItemValue('loai_ct'));
	if (f._action == 'View' || r == -1 || v == '1') return;
	if (!g._validRowBehavior(r)) return;
	if !($func.trim(g._getItemValue(r, g._getColumnOrder('ma_hd'))) != '' && $func.trim(g._getItemValue(r, g._getColumnOrder('s1'))) == '') return;

	if (!q) {
		var o = g._getItem(r, g._getColumnOrder('ma_hd'));
		o.row = r;
		g.request(o, 'AllocatePaymentPhase', 'AllocatePaymentPhase', ['ma_hd', 'tien_nt'], g.$h, null);
	} else return r;
}
function autoAllocatePaymentPhase(f, g) {
	g._q$PaymentPhase = [];
	for (var r = g._rowCount; r >= 1; r--) {
		g._q$PaymentPhase.push(RowAllocatePaymentPhase(f, g, r, true);)
	}

	if (g._q$PaymentPhase.length > 0) {
		var r = g._q$PaymentPhase[0], o = g._getItem(r, g._getColumnOrder('ma_hd'));
		o.row = r;
		g._q$PaymentPhase.splice(0, 1);
		g.request(o, 'AllocatePaymentPhase', 'AllocatePaymentPhase$', ['ma_hd', 'tien_nt'], g.$h, null);
	}
}
/* </flatten> */
			&ImportDetailInsertResult;
			&ImportDetailScript;
			&DowloadScript;
			&ScriptEmptyExternalField;
			&GridExtraToolbarScript;
			&ESG.GridScript;
			&ScriptInsertRetrieveItems;
